package org.brightstats.model;

import java.util.*;
import com.google.gson.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.model.ElementType.Role;

/** Immutable identity-based editing document. Statistical compilation is deliberately separate. */
public final class TypedDiagram {
    private TypedDiagram(){}
    public static final int VERSION=1;
    public record Node(String id,ElementType type,String label,double x,double y,JsonObject properties){
        public Node{identifier(id);Objects.requireNonNull(type);text(label,500);coordinate(x);coordinate(y);if(type.role()==Role.CONNECTION||type.role()==Role.ANNOTATION)throw new IllegalArgumentException("Use a link or annotation for this element type.");properties=TypedDiagram.properties(properties);}
        @Override public JsonObject properties(){return properties.deepCopy();}
        public Node at(double x,double y){return new Node(id,type,label,x,y,properties);}
        public Node named(String label){return new Node(id,type,label,x,y,properties);}
    }
    public record Link(String id,ElementType type,String source,String target,JsonObject properties){
        public Link{identifier(id);identifier(source);identifier(target);Objects.requireNonNull(type);if(type.role()!=Role.CONNECTION)throw new IllegalArgumentException("Choose a connection type.");if(source.equals(target))throw new IllegalArgumentException("Use node variance settings rather than self connections.");properties=TypedDiagram.properties(properties);}
        @Override public JsonObject properties(){return properties.deepCopy();}
    }
    public record Annotation(String id,ElementType type,String attachment,String text,double x,double y,double width,double height){
        public Annotation{identifier(id);Objects.requireNonNull(type);if(type.role()!=Role.ANNOTATION)throw new IllegalArgumentException("Choose a note or label type.");if(attachment==null)attachment="";if(!attachment.isEmpty())identifier(attachment);TypedDiagram.text(text,10000);coordinate(x);coordinate(y);if(!Double.isFinite(width)||!Double.isFinite(height)||width<12||height<12||width>2000||height>2000)throw new IllegalArgumentException("Annotation dimensions must be 12–2000.");}
    }
    public record Document(int version,Family family,String root,List<Node> nodes,List<Link> links,List<Annotation> annotations){
        public Document{if(version!=VERSION)throw new IllegalArgumentException("Unsupported typed diagram version.");Objects.requireNonNull(family);identifier(root);nodes=List.copyOf(nodes);links=List.copyOf(links);annotations=List.copyOf(annotations);validate(family,root,nodes,links,annotations);}
        public Node node(String id){return nodes.stream().filter(node->node.id.equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Unknown diagram node: "+id));}
        public Link link(String id){return links.stream().filter(link->link.id.equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Unknown diagram link: "+id));}
        public Document with(Node value){List<Node> changed=new ArrayList<>(nodes);int index=-1;for(int i=0;i<changed.size();i++)if(changed.get(i).id.equals(value.id))index=i;if(index<0)changed.add(value);else changed.set(index,value);return new Document(version,family,root,changed,links,annotations);}
        public Document with(Link value){List<Link> changed=new ArrayList<>(links);int index=-1;for(int i=0;i<changed.size();i++)if(changed.get(i).id.equals(value.id))index=i;if(index<0)changed.add(value);else changed.set(index,value);return new Document(version,family,root,nodes,changed,annotations);}
        public Document with(Annotation value){List<Annotation> changed=new ArrayList<>(annotations);int index=-1;for(int i=0;i<changed.size();i++)if(changed.get(i).id.equals(value.id))index=i;if(index<0)changed.add(value);else changed.set(index,value);return new Document(version,family,root,nodes,links,changed);}
        public Document move(Set<String> selected,double dx,double dy){coordinate(dx);coordinate(dy);return new Document(version,family,root,nodes.stream().map(node->selected.contains(node.id)&&!node.id.equals(root)?node.at(node.x+dx,node.y+dy):node).toList(),links,annotations.stream().map(note->selected.contains(note.id)?new Annotation(note.id,note.type,note.attachment,note.text,note.x+dx,note.y+dy,note.width,note.height):note).toList());}
        public Document remove(Set<String> selected){if(selected.contains(root))throw new IllegalArgumentException("The model container cannot be removed.");Set<String> removed=new HashSet<>(selected);boolean change;do{change=false;for(var link:links)if(removed.contains(link.source)||removed.contains(link.target))change|=removed.add(link.id);for(var node:nodes)if(node.type==ElementType.DONGLE&&node.properties.has("edge")&&removed.contains(node.properties.get("edge").getAsString()))change|=removed.add(node.id);for(var node:nodes){if(node.type==ElementType.CBSEM_ERROR_TERM){var bindings=links.stream().filter(link->(link.type==ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_ERROR_TERM||link.type==ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_ERROR_TERM)&&(link.source.equals(node.id)||link.target.equals(node.id))).toList();if(!bindings.isEmpty()&&bindings.stream().allMatch(link->removed.contains(link.id)||removed.contains(link.source)||removed.contains(link.target)))change|=removed.add(node.id);}if(node.type==ElementType.GAUSSIAN_COPULA||node.type==ElementType.QUADRATIC_EFFECT||node.type==ElementType.PROCESS_MODEL_QUADRATIC_EFFECT){var bindings=links.stream().filter(link->link.source.equals(node.id)&&link.type.modifier()).toList();if(!bindings.isEmpty()&&bindings.stream().allMatch(link->removed.contains(link.id)||removed.contains(link.target)))change|=removed.add(node.id);}}for(var note:annotations)if(!note.attachment.isEmpty()&&removed.contains(note.attachment))change|=removed.add(note.id);}while(change);return new Document(version,family,root,nodes.stream().filter(node->!removed.contains(node.id)).toList(),links.stream().filter(link->!removed.contains(link.id)).toList(),annotations.stream().filter(note->!removed.contains(note.id)).toList());}
        public JsonObject json(){return new GsonBuilder().serializeNulls().create().toJsonTree(this).getAsJsonObject();}
        public JsonObject fragment(Set<String> selected){Set<String> ids=new HashSet<>(selected);ids.remove(root);for(var link:links)if(ids.contains(link.id)){ids.add(link.source);ids.add(link.target);}Set<String> keptLinks=new HashSet<>();boolean change;do{change=false;for(var link:links)if(ids.contains(link.source)&&ids.contains(link.target))change|=keptLinks.add(link.id);for(var node:nodes)if(node.type==ElementType.DONGLE&&node.properties.has("edge")&&keptLinks.contains(node.properties.get("edge").getAsString()))change|=ids.add(node.id);}while(change);Set<String> invalidAnchors=new HashSet<>();for(var node:nodes)if(node.type==ElementType.DONGLE&&(!node.properties.has("edge")||!keptLinks.contains(node.properties.get("edge").getAsString())))invalidAnchors.add(node.id);boolean prune;do{prune=false;for(var node:nodes)if(ids.contains(node.id)&&node.type==ElementType.DONGLE&&(!node.properties.has("edge")||!keptLinks.contains(node.properties.get("edge").getAsString())))prune|=ids.remove(node.id);prune|=keptLinks.removeIf(id->{var link=link(id);return !ids.contains(link.source)||!ids.contains(link.target);});}while(prune);List<Node> copied=nodes.stream().filter(node->ids.contains(node.id)).toList();List<Link> copiedLinks=links.stream().filter(link->keptLinks.contains(link.id)).toList();List<Annotation> notes=annotations.stream().filter(note->note.attachment.isEmpty()?selected.contains(note.id):ids.contains(note.attachment)||keptLinks.contains(note.attachment)).toList();var output=new JsonObject();output.addProperty("format","bright-stats-typed-fragment");output.addProperty("version",VERSION);output.addProperty("family",family.name());var gson=new GsonBuilder().serializeNulls().create();output.add("nodes",gson.toJsonTree(copied));output.add("links",gson.toJsonTree(copiedLinks));output.add("annotations",gson.toJsonTree(notes));return output;}
        public Paste paste(JsonObject fragment,double dx,double dy){coordinate(dx);coordinate(dy);if(!fragment.has("format")||!fragment.get("format").getAsString().equals("bright-stats-typed-fragment")||fragment.get("version").getAsBigDecimal().intValueExact()!=VERSION||!fragment.get("family").getAsString().equals(family.name()))throw new IllegalArgumentException("Choose a compatible typed diagram fragment.");var gson=new Gson();List<Node> incoming=Arrays.asList(gson.fromJson(fragment.get("nodes"),Node[].class));List<Link> incomingLinks=Arrays.asList(gson.fromJson(fragment.get("links"),Link[].class));List<Annotation> incomingNotes=Arrays.asList(gson.fromJson(fragment.get("annotations"),Annotation[].class));if(incoming.stream().anyMatch(node->node.type==ElementType.ROOT))throw new IllegalArgumentException("Do not paste a second model container.");String temporary=id("root");List<Node> checkNodes=new ArrayList<>(incoming);checkNodes.add(new Node(temporary,ElementType.ROOT,"Fragment",0,0,new JsonObject()));new Document(VERSION,family,temporary,checkNodes,incomingLinks,incomingNotes);Map<String,String> remap=new LinkedHashMap<>();for(var node:incoming)remap.put(node.id,id("node"));for(var link:incomingLinks)remap.put(link.id,id("link"));for(var note:incomingNotes)remap.put(note.id,id("note"));List<Node> merged=new ArrayList<>(nodes);Set<String> usedNames=new HashSet<>();for(var node:nodes)usedNames.add(node.label);for(var node:incoming){var options=node.properties();if(node.type==ElementType.DONGLE&&options.has("edge"))options.addProperty("edge",remap.get(options.get("edge").getAsString()));String label=node.label;if(node.type.role()==Role.NODE||node.type.role()==Role.LEGACY){String base=label;int index=1;while(usedNames.contains(label))label=base+" copy"+(index++==1?"":" "+(index-1));usedNames.add(label);}merged.add(new Node(remap.get(node.id),node.type,label,node.x+dx,node.y+dy,options));}List<Link> mergedLinks=new ArrayList<>(links);for(var link:incomingLinks)mergedLinks.add(new Link(remap.get(link.id),link.type,remap.get(link.source),remap.get(link.target),link.properties));List<Annotation> mergedNotes=new ArrayList<>(annotations);for(var note:incomingNotes)mergedNotes.add(new Annotation(remap.get(note.id),note.type,note.attachment.isEmpty()?"":remap.get(note.attachment),note.text,note.x+dx,note.y+dy,note.width,note.height));return new Paste(new Document(version,family,root,merged,mergedLinks,mergedNotes),Set.copyOf(remap.values()));}
    }
    public record Paste(Document document,Set<String> inserted){public Paste{inserted=Set.copyOf(inserted);}}
    public static Document empty(Family family){String root=id("root");return new Document(VERSION,family,root,List.of(new Node(root,ElementType.ROOT,"Model",0,0,new JsonObject())),List.of(),List.of());}
    public static String id(String prefix){return prefix+"_"+UUID.randomUUID();}
    public static Document parse(String value){boundedJson(value,8*1024*1024,48);return new GsonBuilder().setStrictness(Strictness.STRICT).create().fromJson(value,Document.class);}
    public static void boundedJson(String value,int limit,int depthLimit){if(value==null||value.length()>limit||value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>limit)throw new IllegalArgumentException("Diagram JSON exceeds its size limit.");boolean quoted=false,escaped=false;int depth=0;for(int i=0;i<value.length();i++){char c=value.charAt(i);if(quoted){if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c=='\"')quoted=false;}else if(c=='\"')quoted=true;else if(c=='{'||c=='['){if(++depth>depthLimit)throw new IllegalArgumentException("Diagram JSON exceeds its nesting limit.");}else if(c=='}'||c==']')depth--;}}
    private static void identifier(String value){if(value==null||!value.matches("[A-Za-z][A-Za-z0-9_-]{0,79}"))throw new IllegalArgumentException("Use a stable diagram identifier of at most 80 letters, digits, underscores or hyphens.");}
    private static void text(String value,int limit){if(value==null||value.length()>limit||value.indexOf('\0')>=0)throw new IllegalArgumentException("Diagram text is missing or too long.");}
    private static void coordinate(double value){if(!Double.isFinite(value)||Math.abs(value)>100000)throw new IllegalArgumentException("Diagram coordinates must be finite within +/-100000.");}
    private record JsonLevel(JsonElement value,int depth){}
    private static JsonObject properties(JsonObject value){if(value==null)value=new JsonObject();ArrayDeque<JsonLevel> pending=new ArrayDeque<>();pending.add(new JsonLevel(value,0));int count=0;while(!pending.isEmpty()){var current=pending.removeLast();if(++count>10000||current.depth>32)throw new IllegalArgumentException("Diagram properties exceed their nesting/element budget.");var element=current.value;if(element.isJsonObject())for(var entry:element.getAsJsonObject().entrySet()){text(entry.getKey(),200);pending.add(new JsonLevel(entry.getValue(),current.depth+1));}else if(element.isJsonArray())for(var item:element.getAsJsonArray())pending.add(new JsonLevel(item,current.depth+1));else if(element.isJsonPrimitive()){var primitive=element.getAsJsonPrimitive();if(primitive.isNumber()&&!Double.isFinite(primitive.getAsDouble()))throw new IllegalArgumentException("Diagram property numbers must be finite.");if(primitive.isString())text(primitive.getAsString(),16000);}}if(value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw new IllegalArgumentException("Diagram properties exceed 64 KiB.");return value.deepCopy();}
    private static void validate(Family family,String root,List<Node> nodes,List<Link> links,List<Annotation> notes){if(nodes.size()>1000||links.size()>4000||notes.size()>2000)throw new IllegalArgumentException("Typed diagram exceeds its element budget.");Map<String,Node> byNode=new LinkedHashMap<>();Map<String,Link> byLink=new LinkedHashMap<>();Set<String> all=new HashSet<>();for(var node:nodes){if(!all.add(node.id)||!node.type.supports(family))throw new IllegalArgumentException("Duplicate diagram identity or unsupported node family.");byNode.put(node.id,node);}if(nodes.stream().filter(node->node.type==ElementType.ROOT).count()!=1||!byNode.containsKey(root)||byNode.get(root).type!=ElementType.ROOT)throw new IllegalArgumentException("A typed diagram needs exactly one matching model container.");for(var link:links){if(!all.add(link.id)||!link.type.supports(family)||!byNode.containsKey(link.source)||!byNode.containsKey(link.target)||link.source.equals(root)||link.target.equals(root))throw new IllegalArgumentException("Duplicate, unsupported or dangling diagram connection.");byLink.put(link.id,link);}for(var note:notes){if(!all.add(note.id)||!note.type.supports(family)||!note.attachment.isEmpty()&&!byNode.containsKey(note.attachment)&&!byLink.containsKey(note.attachment))throw new IllegalArgumentException("Duplicate, unsupported or dangling diagram annotation.");if(note.type==ElementType.CONNECTION_LABEL&&!byLink.containsKey(note.attachment)||note.type==ElementType.NODE_EXTERNAL_LABEL&&!byNode.containsKey(note.attachment))throw new IllegalArgumentException("Attach a connection/node label to its matching element.");}for(var node:nodes)if(node.type==ElementType.DONGLE&&node.properties.has("edge")){if(node.properties.has("fraction")){var fraction=node.properties.get("fraction");if(!fraction.isJsonPrimitive()||!fraction.getAsJsonPrimitive().isNumber()||fraction.getAsDouble()<0||fraction.getAsDouble()>1)throw new IllegalArgumentException("Path anchor fraction must be numeric in [0,1].");}var value=node.properties.get("edge");if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString()||!byLink.containsKey(value.getAsString()))throw new IllegalArgumentException("A path anchor must reference a model connection.");anchorCycle(node.id,byNode,byLink,new HashSet<>());}}
    private static void anchorCycle(String id,Map<String,Node> nodes,Map<String,Link> links,Set<String> visited){var node=nodes.get(id);if(node==null||node.type!=ElementType.DONGLE||!node.properties.has("edge"))return;if(visited.size()>8)throw new IllegalArgumentException("Path attachment nesting exceeds eight levels.");if(!visited.add(id))throw new IllegalArgumentException("Path attachment anchors cannot form a dependency cycle.");var link=links.get(node.properties.get("edge").getAsString());anchorCycle(link.source,nodes,links,new HashSet<>(visited));anchorCycle(link.target,nodes,links,new HashSet<>(visited));}
}
